// Horde compatibility for the bundled Freaky Frankenstein 5.4 preset.
// The upstream JSON stays intact in presets.js; this adapter interprets the
// SillyTavern macros and renders its optional markup without trusting raw HTML.
const FREAKY_FRANKENSTEIN_5_4_ID = 'freaky_frankenstein_5_4';

function isFreakyFrankenstein5Preset(preset) {
    return preset?.id === FREAKY_FRANKENSTEIN_5_4_ID;
}

function createFreakyPresetMacroState(config = {}) {
    return {
        vars: Object.create(null),
        maxContext: Math.max(0, Number(config.contextSize) || 0),
        maxResponse: Math.max(0, Number(config.maxTokens) || 0),
        random: Math.random
    };
}

function expandFreakyPresetMacros(source, context) {
    const state = context || createFreakyPresetMacroState();
    const input = String(source ?? '');
    // A balanced scanner is needed: upstream setvar values can contain getvar
    // and roll macros, so stopping at the first }} corrupts the template.
    function expand(text, depth = 0) {
        if (depth > 16) return text;
        let output = '';
        let cursor = 0;
        while (cursor < text.length) {
            const start = text.indexOf('{{', cursor);
            if (start < 0) { output += text.slice(cursor); break; }
            output += text.slice(cursor, start);
            let nested = 1;
            let end = start + 2;
            while (end < text.length - 1 && nested) {
                if (text.startsWith('{{', end)) { nested++; end += 2; }
                else if (text.startsWith('}}', end)) { nested--; end += 2; }
                else end++;
            }
            if (nested) { output += text.slice(start); break; }
            const body = text.slice(start + 2, end - 2);
            const match = /^([a-zA-Z][\w-]*)(?:::([\s\S]*))?$/.exec(body);
            const operation = match?.[1]?.toLowerCase();
            const rest = match?.[2] ?? '';
            let replacement = null;
            if (operation === 'setvar' || operation === 'addvar' || operation === 'incvar') {
                const split = rest.indexOf('::');
                const name = (split < 0 ? rest : rest.slice(0, split)).trim();
                const value = split < 0 ? '' : expand(rest.slice(split + 2), depth + 1);
                if (name) {
                    if (operation === 'setvar') state.vars[name] = value;
                    else state.vars[name] = String((Number(state.vars[name]) || 0)
                        + (operation === 'incvar' ? 1 : Number(value) || 0));
                }
                replacement = '';
            } else if (operation === 'getvar') {
                const split = rest.indexOf('::');
                const name = (split < 0 ? rest : rest.slice(0, split)).trim();
                const fallback = split < 0 ? '' : rest.slice(split + 2);
                replacement = Object.hasOwn(state.vars, name)
                    ? state.vars[name] : expand(fallback, depth + 1);
            } else if (operation === 'maxcontext') {
                replacement = String(state.maxContext);
            } else if (operation === 'maxresponse') {
                replacement = String(state.maxResponse);
            } else if (operation === 'roll') {
                const dice = /^(\d{1,2})d(\d{1,4})$/i.exec(rest.trim());
                if (dice) {
                    const count = Math.min(20, Math.max(1, Number(dice[1])));
                    const sides = Math.min(10000, Math.max(1, Number(dice[2])));
                    let total = 0;
                    for (let i = 0; i < count; i++) total += Math.floor(state.random() * sides) + 1;
                    replacement = String(total);
                }
            }
            output += replacement === null ? text.slice(start, end) : replacement;
            cursor = end;
        }
        return output;
    }
    return expand(input);
}

// World Play has its own canonical state, clock, rules and response contract.
// Only carry FF's optional prose, NPC-voice and presentation improvements into
// World mode. The full preset remains available in Character Chat.
function skipFreakyWorldMechanic(preset, prompt) {
    if (!isFreakyFrankenstein5Preset(preset)) return false;
    const name = String(prompt?.name || '').toLowerCase();
    return /main prompt|time and place|freaky mode|icebreaker test|total output length|npc voice \+ dialogue output|spectacle combat physics|dnd simulator|internal agenda|gm's notebook|inventory, feats|relationships rpg|world sim|chekhov's gun|internal thoughts|internal states|chain of thought|post-history instructions/.test(name);
}

const FREAKY_UNTAGGED_THOUGHTS = /^\s{0,20}([^<\[\s][\s\S]{0,30000}?)(?:\n\s{0,8}[-—_*]{3,}\s{0,8}\n|\n{1,10})(\[\s{0,8}[^\]\n]{0,30}\bTime\b)/i;

function prepareFreakyPresetHistory(text, keepInternalState = true) {
    let result = String(text ?? '');
    // Never feed HTML presentation artifacts or provider thinking back to a
    // model. Retain the newest internal state, which is FF's continuity record.
    result = result.replace(/<!--\s*IMG_PROMPT:[\s\S]{0,4000}?-->/gi, '');
    result = result.replace(FREAKY_UNTAGGED_THOUGHTS, '$2');
    result = result.replace(/<(?:think|thinking|reasoning|internal_monologue)\b[^>]*>[\s\S]*?<\/(?:think|thinking|reasoning|internal_monologue)>/gi, '');
    result = result.replace(/<!--\s*GFX_START\s*-->([\s\S]*?)<!--\s*GFX_END\s*-->/gi,
        (_match, body) => {
            if (/<internal_states\b/i.test(body)) return keepInternalState ? body : '';
            // Letters, signs and phone screens may contain story facts. Drop
            // presentation HTML, not the words the character read.
            return body.replace(/<br\s*\/?\s*>/gi, '\n').replace(/<[^>]{0,500}>/g, '').trim();
        });
    if (!keepInternalState) {
        result = result.replace(/<internal_states\b[^>]*>[\s\S]*?(?:<\/internal_states>|$)/gi, '');
    }
    return result.replace(/\n{3,}/g, '\n\n').trim();
}

function renderFreakyPresetMessage(source) {
    let input = String(source ?? '')
        .replace(/```(?:html|xml|markdown)?\s*(?=<!--\s*GFX_START\s*-->|<internal_states\b|<details\b)/gi, '')
        .replace(/(<!--\s*GFX_END\s*-->|<\/internal_states>|<\/details>)\s*```/gi, '$1');
    input = input.replace(FREAKY_UNTAGGED_THOUGHTS, '<details><summary>💭 Thoughts</summary>$1</details>$2');
    const escape = text => String(text).replace(/[&<>"']/g, char => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
    }[char]));
    const renderText = text => escape(text)
        .replace(/\*\*([^*\n]+)\*\*/g, '<strong>$1</strong>')
        .replace(/\*([^*\n]+)\*/g, '<em>$1</em>')
        .replace(/\n/g, '<br>');
    const colors = new Set(['cyan', 'pink', 'teal', 'orange', 'gold', 'violet', 'salmon', 'orchid', 'yellow', 'plum']);
    const tones = new Set(['shout', 'whisper', 'measured', 'tremble']);
    const relationships = [];
    input = input.replace(/-?[ \t]{0,8}(?:<b[^>]{0,120}>)?\s{0,8}([^<|↔\n]{1,80}?)\s{0,8}(?:<\/b>)?\s{0,8}↔\s{0,8}(?:<b[^>]{0,120}>)?\s{0,8}([^<|\n]{1,80}?)\s{0,8}(?:<\/b>)?\s{0,8}\|\s{0,8}BOND:\s{0,8}([+-]?\d{1,6})\s{0,8}\|\s{0,8}SPARKS?:\s{0,8}(\d{1,6})\s{0,8}\|\s{0,8}GRUDGE:\s{0,8}(\d{1,6})/gi,
        (_match, first, second, bond, sparks, grudge) => {
            const values = [Number(bond), Number(sparks), Number(grudge)];
            const labels = ['Bond', 'Sparks', 'Grudge'];
            const maximums = [20, 15, 10];
            const bars = values.map((value, index) =>
                `<div class="ff-relationship-meter ff-meter-${labels[index].toLowerCase()}">`
                + `<span>${labels[index]}: ${value}</span><span class="ff-meter-track">`
                + `<span style="width:${Math.min(100, Math.abs(value) / maximums[index] * 100)}%"></span>`
                + '</span></div>').join('');
            relationships.push(`<div class="ff-relationship-card"><strong>${escape(first.trim())} ↔ ${escape(second.trim())}</strong>${bars}</div>`);
            return `\uE000R${relationships.length - 1}\uE001`;
        });
    const stack = [];
    let output = '';
    const close = kind => {
        const index = stack.findLastIndex(item => item.kind === kind);
        if (index < 0) return;
        while (stack.length > index) output += stack.pop().close;
    };
    const tokenPattern = /<!--[^]*?-->|<\/?[A-Za-z][^>\n]{0,500}>|[^<]+|</g;
    for (const match of input.matchAll(tokenPattern)) {
        const token = match[0];
        if (token[0] !== '<') {
            const appendText = value => { output += renderText(value).replace(/\uE000R(\d+)\uE001/g,
                (_placeholder, index) => relationships[Number(index)] || ''); };
            // FF5's regex suite repairs summaries accidentally ended by a
            // newline. Do it structurally so malformed output cannot swallow
            // every following nested panel.
            if (stack.at(-1)?.kind === 'summary' && token.includes('\n')) {
                const split = token.indexOf('\n');
                appendText(token.slice(0, split));
                close('summary');
                appendText(token.slice(split));
            } else appendText(token);
            continue;
        }
        if (/^<!--\s*GFX_START\s*-->$/i.test(token)) {
            output += '<div class="ff-gfx">'; stack.push({ kind: 'gfx', close: '</div>' }); continue;
        }
        if (/^<!--\s*GFX_END\s*-->$/i.test(token)) { close('gfx'); continue; }
        if (/^<!--/.test(token)) continue;
        const tag = /^<(\/)?\s*([\w:-]+)/.exec(token);
        if (!tag) { output += escape(token); continue; }
        const closing = !!tag[1];
        const name = tag[2].toLowerCase();
        const colorParts = /^([a-z]+)(?::([a-z]+))?$/.exec(name);
        if (colorParts && colors.has(colorParts[1]) && (!colorParts[2] || tones.has(colorParts[2]))) {
            if (closing) close('color');
            else {
                output += `<span class="ff-dialogue ff-color-${colorParts[1]}${colorParts[2] ? ` ff-tone-${colorParts[2]}` : ''}">`;
                stack.push({ kind: 'color', close: '</span>' });
            }
            continue;
        }
        if (name === 'internal_states') {
            if (closing) close('internal_states');
            else { output += '<div class="ff-internal-states">'; stack.push({ kind: name, close: '</div>' }); }
            continue;
        }
        if (['think', 'thinking', 'reasoning', 'internal_monologue'].includes(name)) {
            if (closing) close('thought');
            else { output += '<details class="rp-scaffold ff-thought"><summary>Thoughts</summary>'; stack.push({ kind: 'thought', close: '</details>' }); }
            continue;
        }
        if (name === 'details') {
            if (closing) close(name);
            else {
                const following = input.slice(match.index + token.length);
                const summary = /^\s*<summary(?:\s[^>]*)?>([^<]{0,200})<\/summary>/i.exec(following)?.[1] || '';
                const theme = /INTERNAL STATES/i.test(summary) ? 'master'
                    : /QUESTS|CHEKHOV|INTERNAL THOUGHTS|INV & SKILLS|INVENTORY|GM.?S? NOTEBOOK/i.test(summary) ? 'purple'
                    : /NPC AGENDAS|NPC LOCATIONS|FACTIONS|BONDS|BOND TRACKER/i.test(summary) ? 'teal'
                    : /PLOT MOMENTUM|DND TASK SIM|WORLD SIM|PHYSICS, ENGINE & WORLD/i.test(summary) ? 'orange' : '';
                output += `<details class="rp-scaffold ff-details${theme ? ` ff-theme-${theme}` : ''}">`;
                stack.push({ kind: name, close: '</details>' });
            }
            continue;
        }
        if (name === 'summary') {
            if (closing) close(name);
            else { output += '<summary>'; stack.push({ kind: name, close: '</summary>' }); }
            continue;
        }
        if (name === 'br' || name === 'hr') { output += name === 'br' ? '<br>' : '<hr>'; continue; }
        if (['b', 'strong', 'i', 'em', 'code'].includes(name)) {
            const htmlName = name === 'b' ? 'strong' : name === 'i' ? 'em' : name;
            if (closing) close(name);
            else { output += `<${htmlName}>`; stack.push({ kind: name, close: `</${htmlName}>` }); }
            continue;
        }
        if (['div', 'span', 'p'].includes(name)) {
            if (closing) close(name);
            else {
                const htmlName = name === 'div' ? 'div' : name;
                const topLevelGraphic = name === 'div' && stack.some(item => item.kind === 'gfx')
                    && !stack.some(item => item.kind === 'div');
                const graphicType = topLevelGraphic
                    ? /font-family\s*:\s*monospace|background\s*:\s*#0a0a0a/i.test(token) ? 'terminal'
                        : /brush script|background\s*:\s*#f4e4d4/i.test(token) ? 'paper'
                            : /background\s*:\s*#121212|border-radius\s*:\s*20px/i.test(token) ? 'phone' : ''
                    : '';
                const className = topLevelGraphic
                    ? ` class="ff-gfx-sheet${graphicType ? ` ff-gfx-${graphicType}` : ''}"` : '';
                output += `<${htmlName}${className}>`;
                stack.push({ kind: name, close: `</${htmlName}>` });
            }
            continue;
        }
        // Unknown tags are text, not executable HTML.
        output += escape(token);
    }
    while (stack.length) output += stack.pop().close;
    return output;
}
